// One-model, two-context supplied-history numerical pilot. No LOCAL/timing arm.
#include "pilot_gate.hpp"
#include "active_kv.hpp"
#include "frozen_reference_primitives.inc"
#include <iomanip>
#include <map>
using namespace hs::n1chain;
static PilotGate*budget=nullptr;
static std::string outdir;
static std::map<llama_context*,std::string>context_names;
static int head(llama_context*c){auto m=llama_get_memory(c);auto lo=llama_memory_seq_pos_min(m,0),hi=llama_memory_seq_pos_max(m,0);need(hi<0||lo==0,"noncontiguous prefix");return hi<0?0:hi+1;}
static void save(const std::string&name,const void*p,size_t n){budget->bytes(n);durable(outdir+"/"+name,std::string(static_cast<const char*>(p),n));}
static void jsonsave(const std::string&name,const PJ&j){durable(outdir+"/"+name,j.dump(2)+"\n");}
static std::vector<float>step(llama_context*c,const std::vector<int>&ids,int pos,const std::string&name){budget->row(ids.size());need(head(c)==pos,"actual native head before decode");::decode(c,ids,pos,false);need(head(c)==pos+int(ids.size()),"partial decode");auto v=::logits(c,151936);for(auto x:v)need(std::isfinite(x),"nonfinite full output");save(name+".f32",v.data(),v.size()*4);jsonsave(name+".op.json",{{"context",context_names.at(c)},{"request_ordinal",budget->state().at("requests")},{"input_ids",ids},{"position",pos},{"rows",ids.size()},{"physical_ubatch",1},{"requested_output_rows",1},{"output_mask","last token only"},{"actual_head_after",head(c)},{"complete_decode",true}});return v;}
static PJ snap(llama_context*c,const std::string&name){int h=head(c);std::string bytes;auto meta=capture_active_kv(c,*budget,*budget,name,h,[&](const std::string&,int,const uint8_t*p,size_t n){for(size_t i=0;i<n;i+=2){uint16_t w;std::memcpy(&w,p+i,2);need((w&0x7c00)!=0x7c00,"nonfinite active KV");}bytes.append(reinterpret_cast<const char*>(p),n);});save(name+".kv",bytes.data(),bytes.size());PJ cells=PJ::array(),tensors=PJ::array();for(auto x:meta.cells_physical_order)cells.push_back({x.physical,x.position,x.sequence});for(auto&t:meta.tensors)tensors.push_back({{"kind",t.kind},{"layer",t.layer},{"dimensions",t.dimensions},{"strides",t.byte_strides},{"active_bytes",t.canonical_active_bytes},{"physical_read_bytes",t.physical_read_bytes},{"callbacks",t.native_tensor_callbacks}});PJ j={{"head",h},{"capacity",meta.capacity},{"cells",cells},{"physical_by_position",meta.physical_by_position},{"tensors",tensors},{"active_bytes",meta.canonical_active_bytes},{"physical_read_bytes",meta.physical_read_bytes},{"native_tensor_callbacks",meta.native_tensor_callbacks},{"format",meta.format}};j["context"]=context_names.at(c);jsonsave(name+".json",j);return j;}
static void compare(const std::string&a,const std::string&b,int oldh=0,int keep=0){std::ifstream x(outdir+"/"+a,std::ios::binary),y(outdir+"/"+b,std::ios::binary);need(bool(x)&&bool(y),"comparison capture missing");
 auto piece=[&](size_t n,size_t offset){std::vector<char>l(n),r(n);x.read(l.data(),n);y.read(r.data(),n);need(size_t(x.gcount())==n&&size_t(y.gcount())==n,"short raw comparison");for(size_t i=0;i<n;++i)if(l[i]!=r[i]){jsonsave("FIRST_DIFFERENCE.json",{{"left",a},{"right",b},{"canonical_byte",offset+i},{"left_byte",uint8_t(l[i])},{"right_byte",uint8_t(r[i])},{"old_head",oldh},{"retained_head",keep},{"rule","STRICT_RAW_FINITE_NO_TOLERANCE"}});throw Blocked("strict raw numeric mismatch");}};
 if(oldh){for(int layer=0;layer<72;++layer)for(int kvh=0;kvh<8;++kvh){x.seekg((size_t(layer)*8+kvh)*oldh*256);piece(keep*256,(size_t(layer)*8+kvh)*keep*256);}}
 else{auto n=std::filesystem::file_size(outdir+"/"+a);need(n==std::filesystem::file_size(outdir+"/"+b),"capture length differs");size_t off=0;while(off<n){size_t take=std::min<size_t>(65536,n-off);piece(take,off);off+=take;}}
}
int main(int argc,char**argv){try{
 need(argc==3,"exact pilot JOB SHA arguments");need(hashfile(argv[1])==argv[2],"actual job SHA differs");PJ j=PJ::parse(textfile(argv[1]));PilotGate gate(j);budget=&gate;outdir=j.at("output");PJ c=PJ::parse(textfile(j.at("case_file")));auto old=c.at("old_materialized_ids").get<std::vector<int>>(),q=c.at("canonical_next_ids").get<std::vector<int>>(),f=c.at("fixed_continuation_ids").get<std::vector<int>>();need(old.size()==186&&q.size()==216&&f.size()==8&&c.at("predicted_retained_head")==88,"exact frozen case geometry");for(auto*a:{&old,&q,&f})for(int t:*a)need(t>=0&&t<151936,"actual token range");
 need(hashfile(j.at("model_path"))=="408b955510e196121c1c375201744783b5c9a43c7956d73fc78df54c66e883d6","model source identity");gate.before_backend_init("pilot");ggml_time_init();llama_backend_init();ggml_backend_dev_t gpu=nullptr;for(size_t i=0;i<ggml_backend_dev_count();++i){auto d=ggml_backend_dev_get(i);if(ggml_backend_dev_type(d)==GGML_BACKEND_DEVICE_TYPE_GPU){need(!gpu,"more than one visible GPU");gpu=d;}}need(gpu,"missing approved GPU");ggml_backend_dev_t devices[]={gpu,nullptr};auto mp=llama_model_default_params();mp.devices=devices;mp.n_gpu_layers=999;mp.split_mode=LLAMA_SPLIT_MODE_NONE;gate.before_model_load("pilot");std::unique_ptr<llama_model,ModelDelete> model(llama_model_load_from_file(j.at("model_path").get<std::string>().c_str(),mp));need(bool(model),"model load failed");auto vocab=llama_model_get_vocab(model.get());need(llama_vocab_n_tokens(vocab)==151936&&llama_vocab_is_eog(vocab,c.at("pending").get<int>()),"vocabulary/pending EOG mismatch");for(int t:f)need(!llama_vocab_is_eog(vocab,t),"fixed continuation contains EOG");
 auto cp=llama_context_default_params();cp.n_ctx=4096;cp.n_batch=4096;cp.n_ubatch=1;cp.n_seq_max=1;cp.n_outputs_max=1;cp.n_outputs_max_per_seq=1;cp.n_threads=2;cp.n_threads_batch=2;cp.type_k=GGML_TYPE_F16;cp.type_v=GGML_TYPE_F16;cp.flash_attn_type=LLAMA_FLASH_ATTN_TYPE_DISABLED;
 gate.before_context("A");std::unique_ptr<llama_context,ContextDelete>A(llama_init_from_model(model.get(),cp));need(bool(A),"A context allocation");gate.before_context("B");std::unique_ptr<llama_context,ContextDelete>B(llama_init_from_model(model.get(),cp));need(bool(B),"B context allocation");for(auto ctx:{A.get(),B.get()})need(llama_n_ctx(ctx)==4096&&llama_n_ubatch(ctx)==1&&head(ctx)==0,"actual equal configuration");context_names[A.get()]="resident-A";context_names[B.get()]="scratch-B";jsonsave("CONFIG.json",{{"n_ctx",4096},{"n_batch",4096},{"n_ubatch",1},{"output_reserve",1},{"threads",2},{"KV","F16"},{"flash_attention",false},{"model_objects",1},{"contexts",2},{"reference","whole initial API with UB1, subsequent q1; original full-source primitives"},{"modules",linux_transfer::modules()}});
 gate.request(0);auto owned=step(A.get(),old,0,"R1-old-output");snap(A.get(),"R1-old-state");jsonsave("R1-pending.json",{{"materialized",186},{"logical_ids",c.at("old_logical_ids")},{"pending",c.at("pending")},{"history","supplied teacher-forced"}});gate.finish();
 gate.request(1);step(B.get(),old,0,"R2-old-output");snap(B.get(),"R2-old-state");compare("R1-old-output.f32","R2-old-output.f32");compare("R1-old-state.kv","R2-old-state.kv");gate.finish();jsonsave("INITIAL_REPEAT_PASS.json",{{"rule","full finite F32 vector and active F16 KV strict bytes"}});
 gate.guard();llama_memory_clear(llama_get_memory(B.get()),true);llama_synchronize(B.get());need(head(B.get())==0,"scratch reset failed");gate.request(2);step(B.get(),std::vector<int>(q.begin(),q.begin()+88),0,"R3-prefix-output");snap(B.get(),"R3-prefix-state");for(int p=88;p<216;++p)step(B.get(),{q[p]},p,"R3-q-"+std::to_string(p));snap(B.get(),"R3-Q-state");for(int i=0;i<8;++i){step(B.get(),{f[i]},216+i,"R3-f-"+std::to_string(i));snap(B.get(),"R3-F-state-"+std::to_string(i));}gate.finish();
 gate.request(3);need(head(A.get())==186,"resident context not retained");need(owned==::logits(A.get(),151936),"resident frontier changed by scratch work");gate.guard();need(llama_memory_seq_rm(llama_get_memory(A.get()),0,88,-1),"trim failed; no rebuild/retry");llama_synchronize(A.get());need(head(A.get())==88,"native retained head mismatch");snap(A.get(),"R4-trimmed-state");jsonsave("R4-reconcile.json",{{"pending",nullptr},{"discarded_old_pending",151645},{"frontier_valid",false},{"retained_head",88},{"native_head",head(A.get())}});compare("R1-old-state.kv","R4-trimmed-state.kv",186,88);compare("R3-prefix-state.kv","R4-trimmed-state.kv");for(int p=88;p<216;++p){step(A.get(),{q[p]},p,"R4-q-"+std::to_string(p));compare("R3-q-"+std::to_string(p)+".f32","R4-q-"+std::to_string(p)+".f32");}snap(A.get(),"R4-Q-state");compare("R3-Q-state.kv","R4-Q-state.kv");for(int i=0;i<8;++i){step(A.get(),{f[i]},216+i,"R4-f-"+std::to_string(i));snap(A.get(),"R4-F-state-"+std::to_string(i));compare("R3-f-"+std::to_string(i)+".f32","R4-f-"+std::to_string(i)+".f32");compare("R3-F-state-"+std::to_string(i)+".kv","R4-F-state-"+std::to_string(i)+".kv");}gate.finish();
 gate.guard();for(auto ctx:{A.get(),B.get()}){llama_memory_clear(llama_get_memory(ctx),true);llama_synchronize(ctx);need(head(ctx)==0,"final reset");}need(gate.state().at("rows")==732&&gate.state().at("requests")==4,"actual terminal budget");jsonsave("RESULT.json",{{"status","PASS_ONE_SUPPLIED_HISTORY_NUMERICAL_BRIDGE"},{"state",gate.state()},{"pending_old",151645},{"pending_after_fixed_materialized_continuation",nullptr},{"greedy_free_generation",false},{"N1a_complete",false},{"performance_claim",false},{"LOCAL_candidate_executed",false}});return 0;
 }catch(const std::exception&e){if(!outdir.empty()){try{jsonsave("STOP_NATIVE.json",{{"status","FAILED_OR_INCOMPLETE_NO_RETRY"},{"reason",e.what()},{"state",PJ::parse(textfile(outdir+"/STATE.json"))}});}catch(...){}}std::cerr<<"PILOT_STOP "<<e.what()<<'\n';return 74;}}
